mapper.select:
SELECT ts.data ->> CONCAT('', #{day}, '') as jsonData, ts.seq as trackServiceSeq from track_service ts

    ts.account_seq = #{acSeq} and ts.hospital_seq = #{hSeq} and ts.disease_seq = #{dSeq}
    AND ts.is_enabled AND ts.status = 'ACTIVE'

select count(ccc.*)
from cm_contents_check ccc

    ccc.account_seq = #{acSeq} and ccc.track_service_seq = #{trackSeq}
AND ccc.contents_seq = #{cSeq}
and ccc.progress = 100 and ccc.is_enabled

select seq ,execution_date ,account_seq ,(select name from account aa where aa.seq = a.account_seq ) as account_name ,step_num from account_step_history a
1 = 1
and a.execution_date = #{executionDate}
and a.account_seq = #{accountSeq}
order by execution_date desc ,account_seq

mapper.update:
	    with upsert as (update account_step_history
                           set step_num = #{stepNum}
                              ,updated_at = now()
                         where execution_date = #{executionDate}
                           and account_seq = #{accountSeq}
                         returning *
                        )
        insert into account_step_history(execution_date,account_seq,step_num)
         select #{executionDate}
               ,#{accountSeq}
               ,#{stepNum}
          where not exists(select * from upsert)

mapper.select:
select aa.seq , aa.created_at , aa.survey_result_str , aa.cancer_type_cd , aa.cancer_type_nm , aa.difficulty_cd , aa.difficulty_nm , aa.aerobic , aa.therapy_cd , aa.therapy_nm , case when (aa.tot_question_step_day_cnt::decimal = 0) then 0 else round(aa.tot_answer_step_day_cnt::decimal / aa.tot_question_step_day_cnt::decimal * 100) end as progress from (select seq , to_char(created_at, 'YYYY-MM-DD HH24:MI:SS') as created_at -- 생성일시 , survey_result survey_result_str , cancer_type_cd , (select val from sys_code_det scd where scd.code = 'CANCER_TYPE_CD' and scd.cd = a.cancer_type_cd and scd.use_yn = 'Y') cancer_type_nm , difficulty_cd , (select val from sys_code_det scd where scd.code = 'DIFFICULTY_CD' and scd.cd = a.difficulty_cd and scd.use_yn = 'Y') difficulty_nm , aerobic , therapy_cd , (select val from sys_code_det scd where scd.code = 'THERAPY_CD' and scd.cd = a.therapy_cd and scd.use_yn = 'Y') therapy_nm , (select count(*) from coaching_exercise_progress_result_hst ceprh where ceprh.account_seq = a.account_seq and ceprh.survey_seq = a.seq) as tot_question_step_day_cnt , (select count(*) from coaching_exercise_progress_result_hst ceprh where ceprh.answer_choice = 'Y' and ceprh.account_seq = a.account_seq and ceprh.survey_seq = a.seq) as tot_answer_step_day_cnt from coaching_exercise_survey_result_hst a
1=1 and a.account_seq = #{accountSeq}
) aa order by aa.created_at desc
